namespace ghidra.app.plugin.core.progmgr;

using docking.action;
using docking.tool;
using ghidra.program.model.listing;

/**
 * Action class for the "Edit Program Options" action
 */
public class ProgramOptionsAction : AbstractProgramNameSwitchingAction {

	public ProgramOptionsAction(ProgramManagerPlugin plugin) : base(plugin, "Program Options")
    {
		MenuData menuData =
			new MenuData(new string[] { ToolConstants.MENU_EDIT, "Program Options" });
		menuData.setMenuGroup(ToolConstants.TOOL_OPTIONS_MENU_GROUP);
		menuData.setMenuSubGroup(ToolConstants.TOOL_OPTIONS_MENU_GROUP + "b");
		setMenuBarData(menuData);
	}

	/* @Override */
	protected void programChanged(Program program) {
		if (program == null) {
			getMenuBarData().setMenuItemName("Program Options");
		}
		else {
			string menuString = "Options for '%s'".formatted(program.getDomainFile().getName());
			getMenuBarData().setMenuItemNamePlain(menuString);
		}
	}

	/* @Override */
	public void actionPerformed(Program program) {
		plugin.showProgramOptions(program);
	}

}
